<style>
.lsg-hero-card{position:relative;overflow:hidden;border-radius:22px;border:1px solid rgba(255,255,255,.08);background:linear-gradient(180deg,rgba(22,28,36,.94) 0,rgba(16,21,28,.98) 100%);box-shadow:0 18px 40px rgba(0,0,0,.18)}body.theme-light .lsg-hero-card,body[data-theme="light"] .lsg-hero-card{background:linear-gradient(180deg,rgba(255,255,255,.98) 0,rgba(245,247,250,.98) 100%);border:1px solid rgba(15,23,42,.08);box-shadow:0 18px 40px rgba(15,23,42,.08)}.lsg-hero-bg{position:absolute;inset:0;pointer-events:none}.lsg-hero-grid{position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.03) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.03) 1px,transparent 1px);background-size:34px 34px;mask-image:radial-gradient(circle at 30% 30%,#000 15%,transparent 85%);opacity:.45}.lsg-hero-orb{position:absolute;border-radius:999px;filter:blur(72px);opacity:.28}.lsg-hero-orb.orb-1{width:260px;height:260px;top:-60px;left:-60px;background:rgba(59,130,246,.40)}.lsg-hero-orb.orb-2{width:220px;height:220px;right:-40px;bottom:-40px;background:rgba(250,204,21,.16)}.lsg-hero-inner{position:relative;z-index:2;padding:28px}.lsg-hero-copy{position:relative;display:flex;flex-direction:column;justify-content:center;padding-right:170px;min-height:100%}.lsg-hero-weather{position:absolute;top:0;right:0}.lsg-hero-weather-inner{display:flex;align-items:center;gap:12px;}.lsg-hero-weather-icon{width:200px;object-fit:contain;display:block;}.lsg-hero-weather-meta{display:flex;flex-direction:column;gap:3px}.lsg-hero-weather-temp{text-align: right;font-size:24px;line-height:1;font-weight:800;color:#fff}.lsg-hero-weather-location{font-size:11px;font-weight:700;color:#94a3b8;max-width:150px;line-height:1.25}.lsg-hero-badge{display:inline-flex;align-items:center;width:max-content;padding:8px 12px;border-radius:999px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.08);font-size:12px;font-weight:700;letter-spacing:.02em;color:#dbe7ff;margin-bottom:14px}.lsg-hero-date{font-size:12px;font-weight:600;letter-spacing:.03em;text-transform:uppercase;color:#94a3b8;margin-bottom:10px}.lsg-hero-title{margin:0 0 12px;font-size:34px;line-height:1.05;font-weight:800;letter-spacing:-.03em;color:#f8fafc}.lsg-hero-text{margin:0;max-width:620px;font-size:14px;line-height:1.75;color:#cbd5e1}.lsg-hero-quote{margin-top:18px;padding-top:16px;border-top:1px solid rgba(255,255,255,.06)}.lsg-hero-quote-body{display:flex;gap:12px;align-items:flex-start}.lsg-hero-quote-icon{width:34px;height:34px;border-radius:10px;display:flex;align-items:center;justify-content:center;background:rgba(250,204,21,.12);border:1px solid rgba(250,204,21,.16);color:#facc15;font-size:13px;flex:0 0 auto}.lsg-hero-quote-content{display:flex;flex-direction:column;gap:6px}.lsg-hero-quote-text{font-size:14px;line-height:1.7;font-weight:500;color:#e2e8f0;font-style:italic}.lsg-hero-quote-author{font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:#94a3b8}.lsg-hero-panel{height:100%;border-radius:18px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.08);padding:18px;backdrop-filter:blur(8px)}.lsg-hero-panel-title{font-size:12px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:#94a3b8;margin-bottom:14px}.lsg-hero-stats{display:flex;flex-direction:column;gap:12px}.lsg-hero-stat{display:flex;align-items:center;gap:12px;padding:12px;border-radius:14px;background:rgba(2,6,23,.22);border:1px solid rgba(255,255,255,.06)}.lsg-hero-stat-icon{width:42px;height:42px;border-radius:12px;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,rgba(37,99,235,.22) 0,rgba(96,165,250,.14) 100%);border:1px solid rgba(96,165,250,.16);color:#93c5fd;font-size:15px}.lsg-hero-stat-value{font-size:24px;line-height:1;font-weight:800;color:#fff;margin-bottom:4px}.lsg-hero-stat-label{font-size:12px;font-weight:600;color:#94a3b8}.lsg-hero-actions{display:grid;grid-template-columns:1fr;gap:10px}.lsg-hero-action{display:flex;align-items:center;gap:12px;padding:12px 14px;border-radius:14px;text-decoration:none;background:rgba(2,6,23,.22);border:1px solid rgba(255,255,255,.06);transition:.2s ease;color:#e2e8f0}.lsg-hero-action:hover{transform:translateY(-1px);background:rgba(255,255,255,.09);color:#fff}.lsg-hero-action-icon{width:38px;height:38px;border-radius:12px;display:flex;align-items:center;justify-content:center;background:rgba(59,130,246,.14);border:1px solid rgba(96,165,250,.14);color:#93c5fd;flex:0 0 auto}.lsg-hero-action-label{flex:1 1 auto;font-size:13px;font-weight:700}.lsg-hero-action-arrow{opacity:.65;font-size:11px}.lsg-hero-action:hover .lsg-hero-action-arrow{opacity:1}.lsg-hero-action:hover .lsg-hero-action-icon{background:rgba(59,130,246,.2)}body.theme-light .lsg-hero-badge,body[data-theme="light"] .lsg-hero-badge{background:rgba(37,99,235,.08);border-color:rgba(37,99,235,.12);color:#1d4ed8}body.theme-light .lsg-hero-title,body[data-theme="light"] .lsg-hero-title,body.theme-light .lsg-hero-stat-value,body[data-theme="light"] .lsg-hero-stat-value,body.theme-light .lsg-hero-weather-temp,body[data-theme="light"] .lsg-hero-weather-temp{color:#0f172a}body.theme-light .lsg-hero-text,body[data-theme="light"] .lsg-hero-text,body.theme-light .lsg-hero-quote-text,body[data-theme="light"] .lsg-hero-quote-text{color:#475569}body.theme-light .lsg-hero-quote,body[data-theme="light"] .lsg-hero-quote{border-top:1px solid rgba(15,23,42,.08)}body.theme-light .lsg-hero-panel,body[data-theme="light"] .lsg-hero-panel{background:rgba(255,255,255,.74);border-color:rgba(15,23,42,.08)}body.theme-light .lsg-hero-stat,body[data-theme="light"] .lsg-hero-stat,body.theme-light .lsg-hero-action,body[data-theme="light"] .lsg-hero-action{background:rgba(15,23,42,.03);border-color:rgba(15,23,42,.06);color:#334155}body.theme-light .lsg-hero-action:hover,body[data-theme="light"] .lsg-hero-action:hover{background:rgba(37,99,235,.06);color:#0f172a}@media (max-width:1199.98px){.lsg-hero-title{font-size:30px}}@media (max-width:991.98px){.lsg-hero-copy{padding-right:0}.lsg-hero-weather{position:static;margin-bottom:14px}.lsg-hero-weather-inner{width:max-content}}@media (max-width:767.98px){.lsg-hero-inner{padding:20px}.lsg-hero-title{font-size:26px}.lsg-hero-text{font-size:13px}.lsg-hero-panel{padding:16px}}@media (max-width:575.98px){.lsg-hero-weather-icon{width:46px;height:46px}.lsg-hero-weather-temp{font-size:21px}}
